local BtnDefaultAnimation = "UIBattlingDialog_TipsBtnNodeDefault"
------------ define ------------

---@class UIBattlingBtnNode
local UIBattlingBtnNode = Class('UIBattlingBtnNode')

function UIBattlingBtnNode:__init()
    self.imgBtnOn = nil
    self.imgBtnOff = nil
    self.compBtn = nil
    self.cgRootPTCActive = nil
    self.tipsHasShowed = nil
end

function UIBattlingBtnNode:__delete()
    self.imgBtnOn = nil
    self.imgBtnOff = nil
    self.compBtn = nil
    self.cgRootPTCActive = nil
    self.tipsHasShowed = nil
end

function UIBattlingBtnNode:Awake()
    if not IsNull(self.controller.transform:Find(ROOT_SWATCH_ON)) then
        self.imgBtnOn = self.controller.transform:Find(ROOT_SWATCH_ON)
    end
    if not IsNull(self.controller.transform:Find(ROOT_SWATCH_OFF)) then
        self.imgBtnOff = self.controller.transform:Find(ROOT_SWATCH_OFF)
    end
    --local transSwitchBG = self.controller.transform:Find("BtnBg")
    --if not IsNull(transSwitchBG) then
        --self.switchImg = transSwitchBG.gameObject:GetComponent(typeof(UISwitchImage))
    --end
    self.compBtn = self.controller:GetComponent(typeof(CS.UnityEngine.UI.Button))
    self.compReceiver = self.controller:GetComponent(typeof(CS.UnityEngine.UI.Extensions.NonDrawingGraphic))

    -- 激活特效
    self.ActiveNode = self.controller.transform:Find("ActiveNode")
    if not isNull(self.ActiveNode) then
        self.ActiveNode.transform.anchoredPosition = Vector2.zero
    end
    --if not IsNull(rootPTCActive) then
    --    self.cgRootPTCActive = KTool.GetOrAddComponent(rootPTCActive.gameObject, typeof(CanvasGroup))
    --end
--@region 关卡提示按钮
    local RT_RootAnim = self.controller.transform:Find("RootAnim")
    if not isNull(RT_RootAnim) then
        self.RootAnimation = RT_RootAnim:GetComponent(typeof(CS.UnityEngine.Animation))
    end
    -- btnIcon是底图，可以切换黑白
    local RT_BtnIcon = self.controller.transform:Find("RootAnim/BtnIcon")
    if not isNull(RT_BtnIcon) then
        self.SImg_BtnIcon = RT_BtnIcon:GetComponent(typeof(UISwitchImage))
    end
    -- imgIcon是图标，也可以切换黑白
    self.RT_ImgIcon = self.controller.transform:Find("RootAnim/BtnIcon/ImgIcon")
    if not isNull(self.RT_ImgIcon) then
        self.SImg_ImgIcon = self.RT_ImgIcon:GetComponent(typeof(UISwitchImage))
        self.AImg_ImgIcon = self.RT_ImgIcon:GetComponent(typeof(CS.Engine.UI.ImageAlterable))
    end
    self.tipsHasShowed = false
--@endregion

--@region 自动战斗按钮
    local RT_BtnIcon1 = self.controller.transform:Find("BtnIcon")
    if not isNull(RT_BtnIcon1) then
        self.SImg_Btn1 = RT_BtnIcon1:GetComponent(typeof(UISwitchImage))
    end
--@endregion
end

function UIBattlingBtnNode:Start()
end

