end

---ChangeBtnState
---改变 按钮显示状态
---@param isOpen boolean
function UIBattlingBtnNode:ChangeBtnState(isOpen)
    if not IsNull(self.ActiveNode) then
        KTool.SetActive(self.ActiveNode, isOpen)
        -- self.ActiveNode.transform.anchoredPosition = isOpen and Vector2.zero or Vector2.New(9999,9999)
    end
end

---ButtonComponent
---获取按钮组件
function UIBattlingBtnNode:ButtonComponent()
    return self.compBtn
end

---SetBtnInteractableState
---设置 按钮 可交互状态
---@param state boolean 
function UIBattlingBtnNode:SetBtnInteractableState(state)
    if IsNull(self.compReceiver) then return end
    self.compReceiver.enabled = state
end

--- 设置图标是否切换黑白
---@param state any
function UIBattlingBtnNode:SetIconUseSwitch(state)
    self.isIconUseSwitch = state
end

--- 为关卡提示的按钮添加这个接口
---@param state any
function UIBattlingBtnNode:OnToggleClicked(state)
    if isNull(self.RootAnimation) or isNull(self.SImg_BtnIcon) or isNull(self.SImg_ImgIcon) then
        return
    end
    if state then
        self.RootAnimation:Stop()
        self.RootAnimation:Play(BtnDefaultAnimation)
        self.SImg_BtnIcon.Status = 2
        if self.isIconUseSwitch then
            self.SImg_ImgIcon.Status = 2
        end
        self.tipsHasShowed = true
    else
        self.RootAnimation:Stop()
        if self.tipsHasShowed then
            self.RootAnimation:Play(BtnDefaultAnimation)
        else
            self.RootAnimation:Play(BtnLoopAnimation)
        end
        self.SImg_BtnIcon.Status = 1
        if self.isIconUseSwitch then
            self.SImg_ImgIcon.Status = 1
        end
    end
end

--- 自动战斗按钮添加一个改变按钮显示图片的接口
---@param isOpen any
function UIBattlingBtnNode:ChangeBtnShow(isOpen)
    if isNull(self.SImg_Btn1) then
        return
    end
    self.SImg_Btn1.Status = isOpen and 2 or 1
end

--- 设置按钮图标
---@param iconPath any
function UIBattlingBtnNode:SetBtnIcon(iconPath)
    if isNotNull(self.AImg_ImgIcon) then
        self.AImg_ImgIcon:LoadSprite(iconPath)
    end
end

--- 设置按钮icon的size
---@param sizeDelta any
function UIBattlingBtnNode:SetIconSize(sizeDelta)
    if isNotNull(self.RT_ImgIcon) then
        self.RT_ImgIcon.sizeDelta = sizeDelta
    end
end

return UIBattlingBtnNode
